begin;
CREATE OR REPLACE FUNCTION reservations_private.read_scoped(p_device_id uuid, p_operation text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_permission text; v_context jsonb; v_event_id uuid; v_booking_id uuid; v_conference_id uuid;
 v_partition uuid; v_limit integer:=coalesce((p_args->>'p_limit')::integer,100);
 v_result jsonb; v_after_created_at timestamptz; v_after_booking_id uuid; v_rows jsonb;
 v_has_more boolean; v_last_created_at timestamptz; v_last_booking_id uuid;
 v_snapshot jsonb; v_room jsonb; v_house jsonb; v_floor jsonb;
begin
 if p_args is null or jsonb_typeof(p_args)<>'object' then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
 if p_args ?| array['scope_partition_id','p_scope_partition_id','device_id','p_device_id','actor_user_id','p_actor_user_id','actor_device_id','p_actor_device_id'] then raise exception 'RESERVATIONS_SCOPE_OVERRIDE_DENIED' using errcode='42501'; end if;
 v_permission:=case when p_operation in('list_conference_options','list_events','get_event','list_event_periods','list_booking_types') then 'reservations.event.view' when p_operation in('list_bookings','get_booking_detail','search_participants_bookings','get_booking_accommodation') then 'reservations.booking.view' when p_operation='get_booking_settlement' then 'reservations.payment.view' when p_operation='get_cancellation_financial_summary' then 'reservations.reports.view' when p_operation='list_booking_payments' then 'reservations.payment.view' when p_operation='list_attendance' then 'reservations.attendance.view' when p_operation='get_operational_state' then 'reservations.operations.view' when p_operation in('get_dashboard_summary','get_report_source_data','get_report_booking_page') then 'reservations.reports.view' end;
 if v_permission is null then raise exception 'RESERVATIONS_OPERATION_NOT_ALLOWED' using errcode='42501'; end if;

 if p_operation='list_conference_options' then
  perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]); v_context:=public.require_effective_module_permission(p_device_id,'reservations',v_permission,null,null);
  return coalesce(public.list_accessible_conferences(p_device_id)->'conferences','[]'::jsonb);
 end if;
 if p_operation='list_events' then
  if p_args ? 'p_conference_id' and not p_args ? 'p_scope_type' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_status','p_limit']); v_conference_id:=nullif(p_args->>'p_conference_id','')::uuid; if v_conference_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=reservations_private.conference_context(p_device_id,v_conference_id,v_permission);
  elsif p_args ? 'p_scope_type' and not p_args ? 'p_conference_id' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_scope_type','p_status','p_limit']); if p_args->>'p_scope_type'<>'standalone' then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=public.require_effective_module_permission(p_device_id,'reservations',v_permission,null,null);
  else raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
  if v_limit<1 or v_limit>5000 then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.start_date desc,x.id),'[]'::jsonb) into v_result from (select e.* from reservations.events e where ((v_conference_id is not null and e.scope_type='conference' and e.conference_id=v_conference_id) or (v_conference_id is null and e.scope_type='standalone' and e.conference_id is null)) and ((p_args->>'p_status') is null or e.status=p_args->>'p_status') order by e.start_date desc,e.id limit v_limit) x; return v_result;
 end if;

 if p_operation in('list_bookings','search_participants_bookings','list_attendance','get_report_source_data') and p_args ? 'p_conference_id' and p_args ? 'p_event_id' and p_args->'p_event_id'='null'::jsonb then
  v_conference_id:=nullif(p_args->>'p_conference_id','')::uuid; if v_conference_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=reservations_private.conference_context(p_device_id,v_conference_id,v_permission);
 elsif p_operation in('get_event','list_event_periods','list_booking_types','list_bookings','search_participants_bookings','list_attendance','get_report_source_data','get_report_booking_page') or (p_operation in('get_dashboard_summary','get_cancellation_financial_summary') and p_args ? 'p_event_id') then
  v_event_id:=nullif(p_args->>'p_event_id','')::uuid; if v_event_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=reservations_private.resolve_event_scope(p_device_id,v_event_id,v_permission);
 elsif p_operation in('get_booking_detail','list_booking_payments','get_operational_state','get_booking_accommodation','get_booking_settlement') then
  v_booking_id:=nullif(p_args->>'p_booking_id','')::uuid; if v_booking_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=reservations_private.resolve_booking_scope(p_device_id,v_booking_id,v_permission);
 elsif p_operation in('get_dashboard_summary','get_cancellation_financial_summary') then
  v_conference_id:=nullif(p_args->>'p_conference_id','')::uuid; if v_conference_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=reservations_private.conference_context(p_device_id,v_conference_id,v_permission);
 end if;
 v_partition:=nullif(v_context->>'scopePartitionId','')::uuid;

 if p_operation='get_event' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id']); select to_jsonb(e)||jsonb_build_object('periods',(select coalesce(jsonb_agg(to_jsonb(p) order by p.display_order),'[]') from reservations.event_periods p where p.event_id=e.id and p.scope_partition_id=e.scope_partition_id),'bookingTypes',(select coalesce(jsonb_agg(to_jsonb(t) order by t.display_order),'[]') from reservations.booking_types t where t.event_id=e.id and t.scope_partition_id=e.scope_partition_id)) into v_result from reservations.events e where e.id=v_event_id and e.scope_partition_id=v_partition;
 elsif p_operation='list_event_periods' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id']); select coalesce(jsonb_agg(to_jsonb(p) order by p.display_order),'[]') into v_result from reservations.event_periods p where p.event_id=v_event_id and p.scope_partition_id=v_partition;
 elsif p_operation='list_booking_types' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id']); select coalesce(jsonb_agg(to_jsonb(t) order by t.display_order),'[]') into v_result from reservations.booking_types t where t.event_id=v_event_id and t.scope_partition_id=v_partition;
 elsif p_operation in('list_bookings','search_participants_bookings') then
  perform platform_private.require_exact_jsonb_keys(p_args,case when p_operation='list_bookings' and v_conference_id is not null then array['p_conference_id','p_event_id','p_limit'] when p_operation='list_bookings' then array['p_event_id','p_limit'] when v_conference_id is not null then array['p_conference_id','p_query','p_event_id','p_limit'] else array['p_event_id','p_query','p_limit'] end); if v_limit<1 or v_limit>5000 then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc,x.id),'[]') into v_result from (select b.*,to_jsonb(p) participant,to_jsonb(e) event,coalesce(pay.total_paid,0) total_paid,greatest(b.price_snapshot-coalesce(pay.total_paid,0),0) remaining_balance,greatest(coalesce(pay.total_paid,0)-b.price_snapshot,0) overpaid_amount,case when coalesce(pay.total_paid,0)=0 then 'unpaid' when pay.total_paid>=b.price_snapshot then 'paid' else 'partial' end payment_status from reservations.bookings_operational b join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id left join lateral(select sum(z.amount) total_paid from reservations.payments z where z.booking_id=b.id and z.scope_partition_id=b.scope_partition_id and z.status='active') pay on true where ((v_event_id is not null and b.event_id=v_event_id and b.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id)) and (p_operation='list_bookings' or lower(p.full_name||' '||p.phone||' '||b.booking_number) like '%'||lower(btrim(p_args->>'p_query'))||'%') order by b.created_at desc,b.id limit v_limit) x;
 elsif p_operation='get_booking_detail' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_booking_id']); select to_jsonb(b)||jsonb_build_object('participant',to_jsonb(p),'event',to_jsonb(e),'payments',(select coalesce(jsonb_agg(to_jsonb(z) order by z.payment_date desc,z.id),'[]') from reservations.payments z where z.booking_id=b.id and z.scope_partition_id=b.scope_partition_id),'attendance',(select coalesce(jsonb_agg(to_jsonb(a) order by a.segment),'[]') from reservations.attendance_records a where a.booking_id=b.id and a.scope_partition_id=b.scope_partition_id),'operationalReview',(select to_jsonb(o) from reservations.operational_reviews o where o.booking_id=b.id and o.scope_partition_id=b.scope_partition_id)) into v_result from reservations.bookings_operational b join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where b.id=v_booking_id and b.scope_partition_id=v_partition;
 elsif p_operation='list_booking_payments' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_booking_id']); select coalesce(jsonb_agg(to_jsonb(z) order by z.payment_date desc,z.id),'[]') into v_result from reservations.payments z where z.booking_id=v_booking_id and z.scope_partition_id=v_partition;
 elsif p_operation='list_attendance' then
  perform platform_private.require_exact_jsonb_keys(p_args,case when v_conference_id is not null then array['p_conference_id','p_event_id','p_limit'] else array['p_event_id','p_limit'] end); if v_limit<1 or v_limit>5000 then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; select coalesce(jsonb_agg(to_jsonb(x) order by x.full_name,x.booking_id,x.segment),'[]') into v_result from (select a.*,p.full_name,b.booking_number from reservations.attendance_records a join reservations.bookings_operational b on b.id=a.booking_id and b.scope_partition_id=a.scope_partition_id join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and b.event_id=v_event_id and b.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) limit v_limit) x;
 elsif p_operation='get_operational_state' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_booking_id']); select to_jsonb(o)||jsonb_build_object('booking',to_jsonb(b),'participant',to_jsonb(p),'totalPaid',coalesce((select sum(z.amount) from reservations.payments z where z.booking_id=b.id and z.scope_partition_id=b.scope_partition_id and z.status='active'),0)) into v_result from reservations.operational_reviews o join reservations.bookings_operational b on b.id=o.booking_id and b.scope_partition_id=o.scope_partition_id join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id where o.booking_id=v_booking_id and o.scope_partition_id=v_partition;
 
 elsif p_operation='get_booking_accommodation' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_booking_id']);
  if v_context->>'scopeType'='standalone' then
   return reservations_private.standalone_accommodation_not_applicable(v_booking_id);
  end if;
  return (
   select jsonb_strip_nulls(jsonb_build_object(
    'bookingId',b.id,'conferenceId',e.conference_id,
    'conferencePersonId',p.person_id,'conferenceParticipationId',cp.id,
    'linked',cp.id is not null,'readyForAccommodation',cp.id is not null,
    'accommodated',o.id is not null,'roomId',r.id,
    'roomNumber',r.room_number,'houseLabel',h.name,'floorLabel',f.name
   ))
   from reservations.bookings_operational b
   join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id
   join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id
   left join public.conference_participations cp on cp.conference_id=e.conference_id and cp.person_id=p.person_id
   left join lateral (
    select x.id,x.room_id from public.conference_accommodation_occupancies x
    where x.conference_id=e.conference_id and x.participation_id=cp.id
    order by x.arrival_day desc,x.id limit 1
   ) o on true
   left join public.conference_accommodation_rooms r on r.id=o.room_id
   left join public.conference_accommodation_floors f on f.id=r.floor_id
   left join public.conference_accommodation_houses h on h.id=f.house_id
   where b.id=v_booking_id
  );
 elsif p_operation='get_dashboard_summary' then
  perform platform_private.require_exact_jsonb_keys(p_args,case when p_args ? 'p_event_id' and not p_args ? 'p_conference_id' then array['p_event_id'] when p_args ? 'p_conference_id' and not p_args ? 'p_event_id' then array['p_conference_id'] else array['__invalid__'] end); return jsonb_build_object('events',(select count(*) from reservations.events e where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id)),'bookings',(select count(*) from reservations.bookings_operational b join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where b.lifecycle_status='active' and ((v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id))),'bookingValue',(select coalesce(sum(b.price_snapshot),0) from reservations.bookings_operational b join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where b.lifecycle_status='active' and ((v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id))),'collected',(select coalesce(sum(z.amount),0) from reservations.payments z join reservations.bookings_operational b on b.id=z.booking_id and b.scope_partition_id=z.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where z.status='active' and b.lifecycle_status='active' and ((v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id))));
 elsif p_operation='get_report_source_data' then
  perform platform_private.require_exact_jsonb_keys(p_args,case when v_conference_id is not null then array['p_conference_id','p_event_id','p_limit'] else array['p_event_id','p_limit'] end); if v_limit<1 or v_limit>5000 then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; return jsonb_build_object('events',(select coalesce(jsonb_agg(to_jsonb(x) order by x.start_date,x.id),'[]') from (select e.* from reservations.events e where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by e.start_date,e.id limit v_limit) x),'periods',(select coalesce(jsonb_agg(to_jsonb(x) order by x.display_order,x.id),'[]') from (select p.* from reservations.event_periods p join reservations.events e on e.id=p.event_id and e.scope_partition_id=p.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by p.display_order,p.id limit v_limit) x),'bookingTypes',(select coalesce(jsonb_agg(to_jsonb(x) order by x.display_order,x.id),'[]') from (select t.* from reservations.booking_types t join reservations.events e on e.id=t.event_id and e.scope_partition_id=t.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by t.display_order,t.id limit v_limit) x),'participants',(select coalesce(jsonb_agg(to_jsonb(x) order by x.full_name,x.id),'[]') from (select distinct p.* from reservations.participants_canonical p join reservations.bookings_operational b on b.participant_id=p.id and b.scope_partition_id=p.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by p.full_name,p.id limit v_limit) x),'bookings',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at,x.id),'[]') from (select b.* from reservations.bookings_operational b join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by b.created_at,b.id limit v_limit) x),'payments',(select coalesce(jsonb_agg(to_jsonb(x) order by x.payment_date,x.id),'[]') from (select z.* from reservations.payments z join reservations.bookings_operational b on b.id=z.booking_id and b.scope_partition_id=z.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by z.payment_date,z.id limit v_limit) x),'attendance',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at,x.id),'[]') from (select a.* from reservations.attendance_records a join reservations.bookings_operational b on b.id=a.booking_id and b.scope_partition_id=a.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by a.created_at,a.id limit v_limit) x),'operationalReviews',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at,x.id),'[]') from (select o.* from reservations.operational_reviews o join reservations.bookings_operational b on b.id=o.booking_id and b.scope_partition_id=o.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by o.created_at,o.id limit v_limit) x));
 elsif p_operation='get_report_booking_page' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id','p_limit','p_after_created_at','p_after_booking_id']); v_after_created_at:=nullif(p_args->>'p_after_created_at','')::timestamptz; v_after_booking_id:=nullif(p_args->>'p_after_booking_id','')::uuid; if not (p_args ? 'p_limit') or v_limit<1 or v_limit>500 or ((v_after_created_at is null)<>(v_after_booking_id is null)) then raise exception 'RESERVATIONS_REPORT_PAGE_ARGUMENTS_INVALID' using errcode='22023'; end if;
  with candidates as materialized(select b.* from reservations.bookings_operational b where b.event_id=v_event_id and b.scope_partition_id=v_partition and (v_after_created_at is null or b.created_at>v_after_created_at or (b.created_at=v_after_created_at and b.id>v_after_booking_id)) order by b.created_at,b.id limit v_limit+1),page as materialized(select * from candidates order by created_at,id limit v_limit) select coalesce(jsonb_agg(jsonb_build_object('booking',to_jsonb(b),'participant',to_jsonb(p),'payments',coalesce((select jsonb_agg(to_jsonb(z) order by z.payment_date,z.id) from reservations.payments z where z.booking_id=b.id and z.scope_partition_id=b.scope_partition_id),'[]'),'attendance',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at,a.id) from reservations.attendance_records a where a.booking_id=b.id and a.scope_partition_id=b.scope_partition_id),'[]'),'operationalReview',(select to_jsonb(o) from reservations.operational_reviews o where o.booking_id=b.id and o.scope_partition_id=b.scope_partition_id)) order by b.created_at,b.id),'[]'),(select count(*)>v_limit from candidates),(array_agg(b.created_at order by b.created_at desc,b.id desc))[1],(array_agg(b.id order by b.created_at desc,b.id desc))[1] into v_rows,v_has_more,v_last_created_at,v_last_booking_id from page b join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id; return jsonb_build_object('rows',v_rows,'hasMore',coalesce(v_has_more,false),'nextCursor',case when coalesce(v_has_more,false) then jsonb_build_object('createdAt',v_last_created_at,'bookingId',v_last_booking_id) else null end);
 end if;
 if p_operation='get_booking_settlement' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_booking_id']);
      return coalesce((select to_jsonb(s)||jsonb_build_object('creditBalance',coalesce(a.balance,0),'creditRevision',coalesce(a.revision,0),'refundDisbursements',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'amount',d.amount,'date',d.disbursed_on,'method',d.payment_method,'methodOther',d.payment_method_other,'reference',d.reference,'reason',d.reason) order by d.disbursed_on,d.created_at,d.id) from reservations.refund_disbursements d where d.scope_partition_id=s.scope_partition_id and d.event_id=credit_booking.event_id and d.booking_id=s.booking_id and d.settlement_id=s.id),'[]'::jsonb)) from reservations.booking_cancellation_settlements s left join reservations.bookings credit_booking on credit_booking.id=s.booking_id and credit_booking.scope_partition_id=s.scope_partition_id left join reservations.person_credit_accounts a on a.scope_partition_id=s.scope_partition_id and a.event_id=credit_booking.event_id and a.person_id=s.person_id where s.booking_id=v_booking_id and s.scope_partition_id=v_partition),'null'::jsonb);
    elsif p_operation='get_cancellation_financial_summary' then
      return (select jsonb_build_object(
        'grossCollected',coalesce(sum(p.amount) filter(where p.status='active'),0),
        'actualRefunds',coalesce((select sum(d.amount) from reservations.refund_disbursements d where d.scope_partition_id=v_partition and (v_event_id is null or d.event_id=v_event_id)),0),
        'netCash',coalesce(sum(p.amount) filter(where p.status='active'),0)-coalesce((select sum(d.amount) from reservations.refund_disbursements d where d.scope_partition_id=v_partition and (v_event_id is null or d.event_id=v_event_id)),0),
        'activeCollection',coalesce(sum(p.amount) filter(where p.status='active' and b.lifecycle_status='active'),0),
        'nonRefundableApologyRevenue',coalesce((select sum(s.non_refundable_amount) from reservations.booking_cancellation_settlements s join reservations.bookings b2 on b2.id=s.booking_id where s.scope_partition_id=v_partition and (v_event_id is null or b2.event_id=v_event_id)),0),
        'outstandingCredits',coalesce((select sum(s.credit_amount-coalesce(redeemed.amount,0)) from reservations.booking_cancellation_settlements s join reservations.bookings credit_booking on credit_booking.id=s.booking_id left join lateral(select sum(entry.amount) amount from reservations.person_credit_entries entry where entry.settlement_id=s.id and entry.entry_kind='redeem') redeemed on true where s.scope_partition_id=v_partition and (v_event_id is null or credit_booking.event_id=v_event_id)),0),
        'refundDisbursements',coalesce((select jsonb_agg(jsonb_build_object('bookingId',d.booking_id,'amount',d.amount,'date',d.disbursed_on,'method',d.payment_method,'methodOther',d.payment_method_other,'reference',d.reference,'reason',d.reason) order by d.disbursed_on,d.created_at,d.id) from reservations.refund_disbursements d where d.scope_partition_id=v_partition and (v_event_id is null or d.event_id=v_event_id)),'[]'::jsonb),
        'pendingRefunds',coalesce((select sum(s.pending_refund_amount) from reservations.booking_cancellation_settlements s join reservations.bookings b3 on b3.id=s.booking_id where s.scope_partition_id=v_partition and (v_event_id is null or b3.event_id=v_event_id)),0),
        'retainedApologyFunds',coalesce((select sum(s.non_refundable_amount) from reservations.booking_cancellation_settlements s join reservations.bookings b4 on b4.id=s.booking_id where s.scope_partition_id=v_partition and (v_event_id is null or b4.event_id=v_event_id)),0),
        'settlements',coalesce((select jsonb_agg(jsonb_build_object('bookingId',b5.id,'bookingNumber',b5.booking_number,'lifecycleStatus',b5.lifecycle_status,'fullName',pc.full_name,'collected',s.collected_amount,'refunded',s.refunded_amount,'pending',s.pending_refund_amount,'retained',s.non_refundable_amount,'refundableAvailable',s.pending_refund_amount+s.non_refundable_amount,'reason',s.reason) order by b5.updated_at desc,b5.id) from reservations.booking_cancellation_settlements s join reservations.bookings b5 on b5.id=s.booking_id and b5.scope_partition_id=s.scope_partition_id join reservations.participants_canonical pc on pc.id=b5.participant_id and pc.scope_partition_id=b5.scope_partition_id where s.scope_partition_id=v_partition and (v_event_id is null or b5.event_id=v_event_id)),'[]'::jsonb)
      ) from reservations.bookings b left join reservations.payments p on p.booking_id=b.id and p.scope_partition_id=b.scope_partition_id where b.scope_partition_id=v_partition and (v_event_id is null or b.event_id=v_event_id));
    end if; if v_result is null then raise exception 'RESERVATIONS_RECORD_NOT_FOUND' using errcode='P0002'; end if; return v_result;
end $function$
;
commit;
